<template>
	<div class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm">
		<label class="mb-3 block text-xs font-semibold uppercase tracking-wide text-ui-ink-gray-400">{{
			judul || 'Tanggal Cuti'
		}}</label>

		<!-- ===== Navigasi bulan ===== -->
		<div class="flex items-center justify-between">
			<button
				type="button"
				class="flex h-9 w-9 items-center justify-center rounded-full text-ui-ink-gray-500 transition active:bg-ui-surface-gray-100 disabled:opacity-30"
				aria-label="Bulan sebelumnya"
				@click="geser(-1)"
			>
				<svg
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="h-5 w-5"
					fill="none"
					stroke="currentColor"
					stroke-width="2"
					stroke-linecap="round"
					stroke-linejoin="round"
				>
					<path d="m15 18-6-6 6-6" />
				</svg>
			</button>
			<span class="text-sm font-semibold text-ui-ink-gray-900"
				>{{ NAMA_BULAN[kursor.getMonth()] }} {{ kursor.getFullYear() }}</span
			>
			<button
				type="button"
				class="flex h-9 w-9 items-center justify-center rounded-full text-ui-ink-gray-500 transition active:bg-ui-surface-gray-100"
				aria-label="Bulan berikutnya"
				@click="geser(1)"
			>
				<svg
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="h-5 w-5"
					fill="none"
					stroke="currentColor"
					stroke-width="2"
					stroke-linecap="round"
					stroke-linejoin="round"
				>
					<path d="m9 18 6-6-6-6" />
				</svg>
			</button>
		</div>

		<!-- ===== Nama hari ===== -->
		<div class="mt-3 grid grid-cols-7 gap-1 text-center">
			<span
				v-for="h in NAMA_HARI"
				:key="h"
				class="py-1 text-2xs font-semibold uppercase tracking-wide text-ui-ink-gray-400"
				>{{ h }}</span
			>
		</div>

		<!-- ===== Grid tanggal ===== -->
		<div class="mt-1 grid grid-cols-7 gap-y-1">
			<div v-for="(sel, i) in sel_grid" :key="i" class="relative">
				<!-- Latar rentang digambar penuh sampai tepi sel supaya menyambung
				     antar tanggal, sementara tombolnya tetap bulat di ujung. -->
				<span
					v-if="sel.tgl && sel.dalamRentang"
					class="absolute inset-y-1 bg-ui-surface-blue-50"
					:class="[
						sel.ujungKiri ? 'left-1/2 rounded-l-full' : 'left-0',
						sel.ujungKanan ? 'right-1/2 rounded-r-full' : 'right-0',
					]"
				></span>

				<button
					v-if="sel.tgl"
					type="button"
					class="relative flex aspect-square w-full items-center justify-center rounded-full text-sm transition"
					:class="kelasTanggal(sel)"
					@click="pilih(sel.iso)"
				>
					{{ sel.tgl.getDate() }}
					<span
						v-if="sel.libur && !sel.terpilih"
						class="absolute bottom-1 h-1 w-1 rounded-full"
						:class="sel.akhirPekan ? 'bg-ui-surface-gray-300' : 'bg-ui-surface-red-400'"
					></span>
				</button>
			</div>
		</div>

		<!-- ===== Keterangan tanda ===== -->
		<div class="mt-3 flex flex-wrap items-center gap-x-4 gap-y-1 text-2xs text-ui-ink-gray-400">
			<span class="flex items-center gap-1.5">
				<span class="h-1 w-1 rounded-full bg-ui-surface-gray-300"></span>akhir pekan
			</span>
			<span class="flex items-center gap-1.5">
				<span class="h-1 w-1 rounded-full bg-ui-surface-red-400"></span>tanggal merah
			</span>
			<span v-if="memuat">memuat hari libur…</span>
		</div>

		<!-- ===== Ringkasan pilihan ===== -->
		<div class="mt-3 rounded-xl bg-ui-surface-gray-50 px-3 py-2.5 text-sm">
			<template v-if="!mulai">
				<span class="text-ui-ink-gray-400">Ketuk tanggal mulai cuti.</span>
			</template>
			<template v-else-if="!selesai">
				<span class="text-ui-ink-gray-600"
					>Mulai <b>{{ labelTanggal(mulai) }}</b>.</span
				>
				<span class="text-ui-ink-gray-400">
					Ketuk tanggal selesai, atau ketuk tanggal yang sama untuk cuti sehari.</span
				>
			</template>
			<template v-else>
				<span class="font-semibold text-ui-ink-gray-900">{{ labelRentang }}</span>
				<span class="text-ui-ink-gray-500">
					· {{ hariKalender }} hari kalender →
					<b :class="hariKerja ? 'text-primary' : 'text-ui-ink-red-600'"
						>{{ hariKerja }} hari kerja</b
					>
				</span>
				<p v-if="dikecualikan.length" class="mt-1 text-xs text-ui-ink-gray-400">
					Tidak dihitung: {{ dikecualikan.join(', ') }}
				</p>
				<p v-if="!hariKerja" class="mt-1 text-xs font-medium text-ui-ink-red-600">
					Seluruh rentang jatuh pada hari libur.
				</p>
			</template>
		</div>
	</div>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
import { createResource } from 'frappe-ui'

const props = defineProps({
	from: { type: String, default: '' },
	to: { type: String, default: '' },
	employee: { type: String, default: '' },
	// Judul kartu; kosong = "Tanggal Cuti".
	judul: { type: String, default: '' },
})
const emit = defineEmits(['update:from', 'update:to'])

const NAMA_BULAN = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]
const SINGKAT = [
	'Jan',
	'Feb',
	'Mar',
	'Apr',
	'Mei',
	'Jun',
	'Jul',
	'Agu',
	'Sep',
	'Okt',
	'Nov',
	'Des',
]
// Pekan dimulai Senin, mengikuti kebiasaan kalender Indonesia.
const NAMA_HARI = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']

function iso(d) {
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const h = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${h}`
}
function dariIso(s) {
	const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? new Date(+m[1], +m[2] - 1, +m[3]) : null
}
function labelTanggal(s) {
	const d = dariIso(s)
	return d ? `${d.getDate()} ${SINGKAT[d.getMonth()]}` : '—'
}

const mulai = computed(() => props.from)
const selesai = computed(() => props.to)
const hariIni = iso(new Date())

// Bulan yang sedang ditampilkan — mengikuti tanggal mulai bila sudah dipilih.
const kursor = ref(dariIso(props.from) || new Date())
function geser(n) {
	kursor.value = new Date(kursor.value.getFullYear(), kursor.value.getMonth() + n, 1)
}

// ===== Hari libur bulan yang tampil =====
const libur = ref({}) // iso -> { keterangan, akhir_pekan }
const memuat = ref(false)

const liburRes = createResource({
	url: 'juragan.api.portal.cuti.get_hari_libur',
	method: 'GET',
	auto: false,
	makeParams: () => {
		// Ambil sebulan sebelum & sesudah supaya rentang yang melintasi bulan
		// tetap terhitung benar tanpa memuat ulang saat navigasi.
		const a = new Date(kursor.value.getFullYear(), kursor.value.getMonth() - 1, 1)
		const b = new Date(kursor.value.getFullYear(), kursor.value.getMonth() + 2, 0)
		const p = { dari: iso(a), sampai: iso(b) }
		if (props.employee) p.employee = props.employee
		return p
	},
	onSuccess: (rows) => {
		const peta = {}
		for (const r of rows || []) {
			peta[String(r.tanggal).slice(0, 10)] = {
				keterangan: r.keterangan,
				akhirPekan: !!r.akhir_pekan,
			}
		}
		libur.value = peta
	},
})

async function muatLibur() {
	memuat.value = true
	try {
		await liburRes.fetch()
	} finally {
		memuat.value = false
	}
}
watch([kursor, () => props.employee], muatLibur, { immediate: true })

// ===== Susun grid =====
const sel_grid = computed(() => {
	const th = kursor.value.getFullYear()
	const bl = kursor.value.getMonth()
	const pertama = new Date(th, bl, 1)
	// getDay(): 0=Minggu. Digeser agar Senin jadi kolom pertama.
	const kosong = (pertama.getDay() + 6) % 7
	const jml = new Date(th, bl + 1, 0).getDate()

	const out = []
	for (let i = 0; i < kosong; i++) out.push({ tgl: null })
	for (let d = 1; d <= jml; d++) {
		const tgl = new Date(th, bl, d)
		const s = iso(tgl)
		const l = libur.value[s]
		const dalam = !!(mulai.value && selesai.value && s >= mulai.value && s <= selesai.value)
		out.push({
			tgl,
			iso: s,
			libur: !!l,
			akhirPekan: l ? l.akhirPekan : false,
			keterangan: l ? l.keterangan : '',
			terpilih: s === mulai.value || s === selesai.value,
			dalamRentang: dalam,
			ujungKiri: dalam && s === mulai.value,
			ujungKanan: dalam && s === selesai.value,
			iniHariIni: s === hariIni,
		})
	}
	return out
})

function kelasTanggal(sel) {
	if (sel.terpilih) return 'bg-primary font-bold text-ui-onPrimary shadow-sm'
	if (sel.dalamRentang) return 'font-medium text-primary'
	if (sel.libur) return 'text-ui-ink-gray-300'
	if (sel.iniHariIni) return 'font-semibold text-ui-ink-gray-900 ring-1 ring-inset ring-primary/40'
	return 'text-ui-ink-gray-700 active:bg-ui-surface-gray-100'
}

// Ketukan pertama menetapkan awal; ketukan kedua menutup rentang. Ketukan yang
// jatuh sebelum awal diperlakukan sebagai awal baru, bukan ditolak — orang
// sering mengoreksi arah setelah melihat kalendernya.
function pilih(s) {
	if (!mulai.value || selesai.value) {
		emit('update:from', s)
		emit('update:to', '')
		return
	}
	if (s < mulai.value) {
		emit('update:from', s)
		return
	}
	emit('update:to', s)
}

// ===== Ringkasan =====
const hariKalender = computed(() => {
	const a = dariIso(mulai.value)
	const b = dariIso(selesai.value)
	if (!a || !b) return 0
	return Math.round((b - a) / 86400000) + 1
})

const rincianRentang = computed(() => {
	const a = dariIso(mulai.value)
	const b = dariIso(selesai.value)
	const hasil = { kerja: 0, dikecualikan: [] }
	if (!a || !b) return hasil
	for (const d = new Date(a); d <= b; d.setDate(d.getDate() + 1)) {
		const s = iso(d)
		const l = libur.value[s]
		if (l) hasil.dikecualikan.push(`${d.getDate()} ${SINGKAT[d.getMonth()]}`)
		else hasil.kerja += 1
	}
	return hasil
})
const hariKerja = computed(() => rincianRentang.value.kerja)
const dikecualikan = computed(() => rincianRentang.value.dikecualikan)

const labelRentang = computed(() => {
	const a = dariIso(mulai.value)
	const b = dariIso(selesai.value)
	if (!a || !b) return '—'
	if (mulai.value === selesai.value) return `${a.getDate()} ${SINGKAT[a.getMonth()]}`
	if (a.getMonth() === b.getMonth())
		return `${a.getDate()} s.d. ${b.getDate()} ${SINGKAT[b.getMonth()]}`
	return `${a.getDate()} ${SINGKAT[a.getMonth()]} s.d. ${b.getDate()} ${SINGKAT[b.getMonth()]}`
})
</script>
